// ============================================================================
// COMMON HELPERS (JScript / ES3 compatible - no let/const, no Array.indexOf/forEach, no JSON)
// ============================================================================
var WARNINGS = [];
var CONNS = [];   // created connectors: {id, frm, to, kind} - used to style diagram links
var EL = {};      // element name -> EA.Element
var PKG = {};     // key -> EA.Package
var STATS = { packages: 0, classes: 0, enums: 0, tables: 0, attributes: 0, methods: 0, tags: 0, connectors: 0, diagrams: 0, diagramObjects: 0, notes: 0 };
var EXPECT = { attrs: {}, connectors: 0, diagramObjects: {} };

function out(msg) {
    try { Session.Output(String(msg)); } catch (e) { }
}
function warn(msg) {
    WARNINGS[WARNINGS.length] = String(msg);
    out("  WARN: " + msg);
}
function errText(e) {
    if (e == null) return "unknown error";
    if (e.message) return String(e.message);
    if (e.description) return String(e.description);
    return String(e);
}
function rgb(r, g, b) { return r + (g * 256) + (b * 65536); }

function saveObj(o, what) {
    var ok = true;
    try { ok = o.Update(); }
    catch (e) { warn(what + ": Update() raised: " + errText(e)); return false; }
    if (ok === false) {
        var m = "";
        try { m = o.GetLastError(); } catch (e2) { }
        warn(what + ": Update() returned false. " + m);
        return false;
    }
    return true;
}

function parseMult(m) {
    var s = String(m == null ? "" : m);
    s = s.replace(/^\s+|\s+$/g, "");
    if (s == "") return ["1", "1"];
    var i = s.indexOf("..");
    if (i < 0) {
        if (s == "*") return ["0", "*"];
        return [s, s];
    }
    return [s.substring(0, i), s.substring(i + 2)];
}

function addTag(coll, name, value, what) {
    if (value == null) return;
    var v = String(value);
    if (v == "") return;
    var t = coll.AddNew(name, "");
    if (v.length > 240) { t.Value = "<memo>"; t.Notes = v; }
    else { t.Value = v; }
    if (saveObj(t, what + " tag " + name)) STATS.tags++;
}

function childIndex(parent, name) {
    var i;
    for (i = 0; i < parent.Packages.Count; i++) {
        if (parent.Packages.GetAt(i).Name == name) return i;
    }
    return -1;
}

function addPackage(parent, name, notes) {
    var p = parent.Packages.AddNew(name, "");
    p.Notes = notes == null ? "" : String(notes);
    saveObj(p, "package " + name);
    parent.Packages.Refresh();
    STATS.packages++;
    return p;
}

function getOrCreateChild(parent, name) {
    var idx = childIndex(parent, name);
    if (idx >= 0) return parent.Packages.GetAt(idx);
    return addPackage(parent, name, "");
}

function freshPackage(parent, name, notes) {
    var idx = childIndex(parent, name);
    while (idx >= 0) {
        if (!CFG.replaceExisting) {
            throw new Error("Package '" + name + "' already exists. Set CFG.replaceExisting = true to replace it, or rename/delete it first.");
        }
        out("Replacing existing package '" + name + "' ...");
        parent.Packages.DeleteAt(idx, false);
        parent.Packages.Refresh();
        idx = childIndex(parent, name);
    }
    return addPackage(parent, name, notes);
}

function resolveBase() {
    var p = null;
    if (CFG.useSelectedPackageAsParent) {
        try { p = Repository.GetTreeSelectedPackage(); } catch (e) { p = null; }
    }
    if (p == null) {
        if (Repository.Models.Count < 1) throw new Error("The repository has no model root.");
        p = Repository.Models.GetAt(0);
    }
    return p;
}

function colorize(el, c) {
    try { el.SetAppearance(0, 0, c); } catch (e) { }
    try { el.SetAppearance(1, 0, c); } catch (e2) { }
}

function addElement(pkg, name, type, stereo, notes, alias) {
    var e = pkg.Elements.AddNew(name, type);
    if (stereo != null && stereo != "") e.Stereotype = stereo;
    e.Notes = notes == null ? "" : String(notes);
    if (alias != null && alias != "") e.Alias = alias;
    saveObj(e, type + " " + name);
    return e;
}

function newDiagram(pkg, name, notes) {
    var d = pkg.Diagrams.AddNew(name, "Class");
    d.Notes = notes == null ? "" : String(notes);
    saveObj(d, "diagram " + name);
    pkg.Diagrams.Refresh();
    STATS.diagrams++;
    return d;
}

function placeObject(diag, el, x, y, w, h) {
    var pos = "l=" + Math.round(x) + ";r=" + Math.round(x + w) + ";t=" + Math.round(0 - y) + ";b=" + Math.round(0 - (y + h)) + ";";
    var o = diag.DiagramObjects.AddNew(pos, "");
    o.ElementID = el.ElementID;
    if (saveObj(o, "diagram object in " + diag.Name)) {
        STATS.diagramObjects++;
        EXPECT.diagramObjects[diag.Name] = (EXPECT.diagramObjects[diag.Name] || 0) + 1;
    }
    return o;
}

// generic connector.  o: name, stereo, notes, direction, cs, ss, cr, sr, cnav, snav, agg (client end aggregation 0/1/2), fk (object)
function connect(client, supplier, type, o) {
    var c = client.Connectors.AddNew(o.name == null ? "" : String(o.name), type);
    c.SupplierID = supplier.ElementID;
    if (o.stereoEx) { c.StereotypeEx = o.stereoEx; }
    else if (o.stereo) { c.Stereotype = o.stereo; }
    if (o.notes) c.Notes = String(o.notes);
    if (o.direction) c.Direction = o.direction;
    if (o.styleEx) c.StyleEx = o.styleEx;
    if (o.cr != null) c.ClientEnd.Role = String(o.cr);
    if (o.cs != null) c.ClientEnd.Cardinality = String(o.cs);
    if (o.sr != null) c.SupplierEnd.Role = String(o.sr);
    if (o.ss != null) c.SupplierEnd.Cardinality = String(o.ss);
    if (o.cnav != null) c.ClientEnd.Navigable = o.cnav;
    if (o.snav != null) c.SupplierEnd.Navigable = o.snav;
    if (o.agg != null) c.ClientEnd.Aggregation = o.agg;
    var ok = saveObj(c, "connector " + type + " " + client.Name + " -> " + supplier.Name);
    if (ok) {
        STATS.connectors++; EXPECT.connectors++;
        CONNS[CONNS.length] = { id: c.ConnectorID, frm: client.Name, to: supplier.Name, kind: o.kind };
    }
    try { c.ClientEnd.Update(); c.SupplierEnd.Update(); } catch (e) { }
    client.Connectors.Refresh();
    return ok ? c : null;
}

function finishReport(title, extra) {
    var lines = [];
    lines[lines.length] = title;
    lines[lines.length] = "";
    lines[lines.length] = "Packages: " + STATS.packages + " | Diagrams: " + STATS.diagrams + " | Diagram objects: " + STATS.diagramObjects;
    lines[lines.length] = extra;
    lines[lines.length] = "Attributes/columns: " + STATS.attributes + " | Operations (PK/FK): " + STATS.methods + " | Tagged values: " + STATS.tags + " | Connectors: " + STATS.connectors;
    lines[lines.length] = "";
    if (WARNINGS.length == 0) lines[lines.length] = "Warnings: none";
    else {
        lines[lines.length] = "Warnings: " + WARNINGS.length + " (see the Script output window)";
        var k;
        for (k = 0; k < WARNINGS.length && k < 8; k++) lines[lines.length] = "  - " + WARNINGS[k];
    }
    var text = lines.join("\n");
    out(text);
    return text;
}

function showMessage(text) {
    try { Session.Prompt(text, 1); } catch (e) { }
}

// ---- theme helpers (colours are "#RRGGBB" strings in the generated data) ----
function hexRgb(h) {
    var s = String(h).replace("#", "");
    return parseInt(s.substring(0, 2), 16) + parseInt(s.substring(2, 4), 16) * 256 + parseInt(s.substring(4, 6), 16) * 65536;
}
// style of a diagram object: {fill, font, border, bw}
function styleObject(o, st) {
    if (st == null) return;
    try { o.BackgroundColor = hexRgb(st.fill); } catch (e1) { }
    try { o.FontColor = hexRgb(st.font); } catch (e2) { }
    try { o.BorderColor = hexRgb(st.border); } catch (e3) { }
    try { o.BorderLineWidth = st.bw; } catch (e4) { }
    try { o.Update(); } catch (e5) { }
}
// default (element) appearance, so the colours also survive in other diagrams
function styleElement(el, st) {
    if (st == null) return;
    var sc;
    for (sc = 0; sc <= 1; sc++) {
        try { el.SetAppearance(sc, 0, hexRgb(st.fill)); } catch (e1) { }
        try { el.SetAppearance(sc, 1, hexRgb(st.font)); } catch (e2) { }
        try { el.SetAppearance(sc, 2, hexRgb(st.border)); } catch (e3) { }
        try { el.SetAppearance(sc, 3, st.bw); } catch (e4) { }
    }
}

// ============================================================================
// PDM ENGINE (MES production definition) - domains, group packages, tables, columns, PK/FK, semantic relations,
// Databricks-styled diagrams with domain and group boundaries.
// ============================================================================
var THEME = {
    fk:  { color: "#1B3139", width: 1 },   // foreign key inside a domain: Databricks navy
    xd:  { color: "#FF3621", width: 2 },   // foreign key across domains: Databricks orange
    ext: { color: "#6B7C85", width: 1 }    // reference to an external table: grey
};

function addOperation(el, name, stereo, cols, notes, what) {
    var m = el.Methods.AddNew(name, "");
    m.Stereotype = stereo;
    m.Notes = notes == null ? "" : String(notes);
    if (saveObj(m, what)) {
        STATS.methods++;
        var i;
        for (i = 0; i < cols.length; i++) {
            try {
                var p = m.Parameters.AddNew(cols[i], "");
                saveObj(p, what + " parameter " + cols[i]);
            } catch (e) { warn(what + ": parameter " + cols[i] + " failed: " + errText(e)); }
        }
        try { m.Parameters.Refresh(); } catch (e2) { }
    }
    return m;
}

function sqlQuote(s) { return String(s).replace(/'/g, "''"); }
function defText(n) {
    var s = String(n), i = s.indexOf("\n");
    if (i >= 0) s = s.substring(0, i);
    s = s.replace(/^Definition: /, "");
    if (s.length > 160) s = s.substring(0, 157) + "...";
    return sqlQuote(s);
}
// Databricks DDL of one table, built from the model data
function ddlOf(t) {
    var lines = [], i, c, s, k;
    for (i = 0; i < t.cols.length; i++) {
        c = t.cols[i];
        s = "  " + c.name + " " + c.type;
        if (c.gen != "") s += " " + c.gen;
        if (c.notNull) s += " NOT NULL";
        if (c.dflt != "") s += " DEFAULT " + c.dflt;
        s += " COMMENT '" + defText(c.notes) + "'";
        lines[lines.length] = s;
    }
    lines[lines.length] = "  CONSTRAINT " + t.pk.name + " PRIMARY KEY (" + t.pk.cols.join(", ") + ")";
    for (i = 0; i < t.cols.length; i++) {
        c = t.cols[i];
        if (c.en != null) {
            var vals = [];
            for (k = 0; k < c.en.length; k++) vals[vals.length] = "'" + sqlQuote(c.en[k]) + "'";
            lines[lines.length] = "  CONSTRAINT ck_" + t.shortName + "_" + c.name + " CHECK (" + c.name + " IN (" + vals.join(", ") + "))";
        }
    }
    var txt = "CREATE TABLE IF NOT EXISTS " + t.name + " (\n" + lines.join(",\n") + "\n)\nUSING DELTA\nCOMMENT '" + sqlQuote(t.comment) + "'";
    if (t.cluster != "") txt += "\nCLUSTER BY (" + t.cluster + ")";
    txt += "\nTBLPROPERTIES ('mes.kind' = '" + t.kind + "', 'mes.domain' = '" + t.domain + "');";
    if (t.fkall.length > 0) {
        txt += "\n\n-- foreign keys (informational)";
        for (i = 0; i < t.fkall.length; i++) txt += "\nALTER TABLE " + t.name + " ADD CONSTRAINT " + t.fkall[i].name + " FOREIGN KEY (" + t.fkall[i].col + ") REFERENCES " + t.fkall[i].ref + "(id);";
    }
    return txt;
}

function createTable(pkg, t) {
    var e = addElement(pkg, t.name, "Class", "table", t.notes, "");
    var i;
    for (i = 0; i < t.cols.length; i++) {
        var c = t.cols[i];
        var a = e.Attributes.AddNew(c.name, c.type);
        a.Stereotype = "column";
        a.Visibility = "Public";
        a.AllowDuplicates = c.notNull ? true : false;   // EA database column flag: Not Null
        if (c.pk) { try { a.IsOrdered = true; } catch (e1) { } }   // EA database column flag: Primary Key
        a.Notes = c.notes == null ? "" : String(c.notes);
        a.Pos = i;
        if (saveObj(a, "column " + t.name + "." + c.name)) STATS.attributes++;
    }
    e.Attributes.Refresh();
    addOperation(e, t.pk.name, "PK", t.pk.cols, "Primary key of " + t.name + ": " + t.pk.cols.join(", "), "PK " + t.name);
    for (i = 0; i < t.fks.length; i++) {
        addOperation(e, t.fks[i].name, "FK", t.fks[i].cols,
            "Foreign key " + t.fks[i].cols.join(", ") + " -> " + t.fks[i].parent + ".id", "FK " + t.name);
    }
    e.Methods.Refresh();
    var k;
    for (k in t.tags) { if (k != "ddl") addTag(e.TaggedValues, k, t.tags[k], "table " + t.name); }
    addTag(e.TaggedValues, "ddl", ddlOf(t), "table " + t.name);
    e.TaggedValues.Refresh();
    styleElement(e, t.style);
    EXPECT.attrs[t.name] = t.cols.length;
    EL[t.name] = e;
    STATS.tables++;
    return e;
}

function createStub(pkg, st) {
    var e = addElement(pkg, st.name, "Class", "external", st.notes, "");
    var i;
    for (i = 0; i < st.attrs.length; i++) {
        var a = e.Attributes.AddNew(st.attrs[i][0], st.attrs[i][1]);
        a.Visibility = "Public";
        a.Notes = "Stub attribute: the table belongs to a module outside the production definition model; see the uploaded MES schema for the full definition.";
        a.Pos = i;
        if (saveObj(a, "stub attribute " + st.name + "." + st.attrs[i][0])) STATS.attributes++;
    }
    e.Attributes.Refresh();
    addTag(e.TaggedValues, "status", "external table - outside the production definition model, no DDL", "stub " + st.name);
    e.TaggedValues.Refresh();
    styleElement(e, st.style);
    EXPECT.attrs[st.name] = st.attrs.length;
    EL[st.name] = e;
    STATS.classes++;
    return e;
}

function createRelations() {
    var i, r;
    for (i = 0; i < DATA.rels.length; i++) {
        r = DATA.rels[i];
        if (r.stub && !CFG.includeExternalStubs) continue;
        if (EL[r.frm] == null || EL[r.to] == null) { warn("relation skipped, element missing: " + r.frm + " -> " + r.to); continue; }
        connect(EL[r.frm], EL[r.to], "Association", {
            name: r.label, stereoEx: "EAUML::FK", notes: r.notes, kind: r.kind,
            direction: "Source -> Destination",
            styleEx: "FKINFO=SRC=" + r.fkName + ":DST=" + r.pkName + ":;",
            cr: r.fkName, sr: r.pkName, cs: r.cs, ss: r.ss,
            cnav: "Non-Navigable", snav: "Navigable"
        });
        if ((i + 1) % 100 == 0) out("  ... " + (i + 1) + " of " + DATA.rels.length + " relations");
    }
}

// colour, width and routing of the connector lines inside one diagram
function styleLinks(diag, onDiagram, hideLabels) {
    var styled = 0, i, c, link, existing = {}, d2 = diag;
    try { d2 = Repository.GetDiagramByID(diag.DiagramID); } catch (e0) { d2 = diag; }
    try { d2.DiagramLinks.Refresh(); } catch (e1) { }
    try {
        for (i = 0; i < d2.DiagramLinks.Count; i++) { link = d2.DiagramLinks.GetAt(i); existing[link.ConnectorID] = link; }
    } catch (e2) { }
    for (i = 0; i < CONNS.length; i++) {
        c = CONNS[i];
        if (!onDiagram[c.frm] || !onDiagram[c.to]) continue;
        link = existing[c.id];
        if (link == null) {
            try { link = d2.DiagramLinks.AddNew("", ""); link.ConnectorID = c.id; link.Update(); } catch (e3) { link = null; }
        }
        if (link == null) continue;
        var th = THEME[c.kind] == null ? THEME.fk : THEME[c.kind];
        try { link.LineColor = hexRgb(th.color); } catch (e4) { }
        try { link.LineWidth = th.width; } catch (e5) { }
        if (CFG.linkStyle > 0) { try { link.LineStyle = CFG.linkStyle; } catch (e6) { } }
        if (hideLabels) { try { link.HiddenLabels = true; } catch (e7) { } }
        try { link.Update(); styled++; } catch (e8) { }
    }
    return styled;
}

var LINKS_STYLED = 0;

function createDiagrams() {
    var first = null;
    var i, j;
    for (i = 0; i < DATA.diagrams.length; i++) {
        var d = DATA.diagrams[i];
        if (d.pkg != "overview" && !CFG.createDomainDiagrams) continue;
        var pkg = PKG[d.pkg];
        if (pkg == null) { warn("no package for diagram " + d.name); continue; }
        out("  diagram: " + d.name);
        var diag = newDiagram(pkg, d.name, d.notes);
        var onDiagram = {};
        for (j = 0; j < d.items.length; j++) {
            var it = d.items[j];
            var el = null;
            if (it.kind == "note") {
                el = addElement(pkg, "", "Note", "", it.text, "");
                styleElement(el, it.style);
                STATS.notes++;
            } else if (it.kind == "boundary") {
                el = addElement(pkg, it.name, "Boundary", "", it.notes == "" ? ("Boundary: " + it.name) : it.notes, "");
                styleElement(el, it.style);
                STATS.boundaries++;
            } else {
                el = EL[it.name];
                if (el == null) continue;      // stub disabled by configuration
                onDiagram[it.name] = true;
            }
            var o = placeObject(diag, el, it.x, it.y, it.w, it.h);
            if (CFG.theme) styleObject(o, it.style);
        }
        pkg.Elements.Refresh();
        diag.DiagramObjects.Refresh();
        saveObj(diag, "diagram " + d.name);
        if (CFG.theme) LINKS_STYLED += styleLinks(diag, onDiagram, d.hideLabels);
        try { Repository.ReloadDiagram(diag.DiagramID); } catch (e4) { }
        if (first == null) first = diag;
    }
    return first;
}

function verify() {
    var k, bad = 0;
    for (k in EXPECT.attrs) {
        if (EL[k] == null) continue;
        var n = EL[k].Attributes.Count;
        if (n != EXPECT.attrs[k]) { warn("verify: " + k + " has " + n + " columns, expected " + EXPECT.attrs[k]); bad++; }
    }
    if (STATS.connectors != EXPECT.connectors) { warn("verify: connector counter mismatch"); bad++; }
    out("Verification: " + (bad == 0 ? "all column counts match the model." : bad + " mismatch(es)."));
}

function build() {
    var i, j;
    out("=== MAP UDM - M1 Manufacturing Definition - production MES PDM ===");
    STATS.boundaries = 0;
    var base = resolveBase();
    var parent = base;
    for (i = 0; i < CFG.parentPath.length; i++) parent = getOrCreateChild(parent, CFG.parentPath[i]);
    var root = freshPackage(parent, CFG.rootName, DATA.meta.rootNotes);
    PKG["root"] = root;
    PKG["overview"] = addPackage(root, "00_Overview_PDM", DATA.meta.overviewNotes);
    for (i = 0; i < DATA.domains.length; i++) {
        var dm = DATA.domains[i];
        PKG[dm.id] = addPackage(root, dm.pkg, dm.notes);
        for (j = 0; j < dm.groups.length; j++) {
            PKG[dm.id + "|" + dm.groups[j].name] = addPackage(PKG[dm.id], dm.groups[j].name, "Group '" + dm.groups[j].name + "' of domain " + dm.id + " " + dm.name + ".");
        }
    }
    if (CFG.includeExternalStubs) PKG["stubs"] = addPackage(root, "99_External_References", DATA.meta.stubNotes);

    out("Creating " + DATA.tables.length + " tables with columns and keys (this takes a few minutes) ...");
    for (i = 0; i < DATA.tables.length; i++) {
        var t = DATA.tables[i];
        createTable(PKG[t.domain + "|" + t.group], t);
        if ((i + 1) % 20 == 0) out("  ... " + (i + 1) + " of " + DATA.tables.length + " tables");
    }
    if (CFG.includeExternalStubs) {
        out("Creating external reference tables ...");
        for (i = 0; i < DATA.stubs.length; i++) createStub(PKG["stubs"], DATA.stubs[i]);
    }
    out("Creating foreign keys and semantic relations ...");
    createRelations();
    out("Creating diagrams ...");
    var first = createDiagrams();
    verify();
    return { root: root, first: first };
}

function main() {
    var uiOff = false;
    var result = null;
    var failed = null;
    try { Repository.EnableUIUpdates = false; uiOff = true; } catch (e0) { }
    try { result = build(); }
    catch (err) { failed = err; }
    if (uiOff) { try { Repository.EnableUIUpdates = true; } catch (e1) { } }
    if (failed != null) {
        var m = "PDM script aborted: " + errText(failed) + "\n\nFix the cause and run the script again (it replaces its own package '" + CFG.rootName + "').";
        out(m);
        showMessage(m);
        return;
    }
    try { Repository.RefreshModelView(result.root.PackageID); } catch (e2) { }
    try { if (result.first != null) Repository.OpenDiagram(result.first.DiagramID); } catch (e3) { }
    var styleLine = CFG.theme ? ("Connector lines styled: " + LINKS_STYLED + " (across all diagrams)") : "Theme: off";
    var text = finishReport("PDM created: MAP_UDM > M1_ManufacturingDefinition > " + CFG.rootName,
        "Tables: " + STATS.tables + " | External tables: " + (CFG.includeExternalStubs ? STATS.classes : 0) + " | Boundaries: " + STATS.boundaries + " | Notes: " + STATS.notes + "\n" + styleLine);
    showMessage(text);
}

main();
